package com.hbm.machine.radar;
import net.minecraft.core.BlockPos;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent;
/** Actual source NBTControl keys are applied only to the matching loaded real radar in the player's dimension. */
public record RadarControl(BlockPos position,CompoundTag data)implements CustomPacketPayload{public static final Type<RadarControl> TYPE=new Type<>(RadarContent.id("radar_control"));public static final StreamCodec<RegistryFriendlyByteBuf,RadarControl> CODEC=StreamCodec.of((b,p)->{b.writeBlockPos(p.position);b.writeNbt(p.data);},b->new RadarControl(b.readBlockPos(),b.readNbt()));public RadarControl{position=position.immutable();data=data.copy();}@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}public static void register(RegisterPayloadHandlersEvent event){event.registrar("1").playToServer(TYPE,CODEC,(p,c)->c.enqueueWork(()->{var player=c.player();if(player.level().hasChunkAt(p.position)&&player.level().getBlockEntity(p.position) instanceof RadarBlockEntity radar)radar.control(player,p.data);}));}}
